    ["Presence penalty"] = "Штраф за присутствие",
    ["Frequency penalty"] = "Штраф за частоту",
    ["Advanced parameters (JSON)"] = "Расширенные параметры (JSON)",
    ["Extra settings added to every reply, written as a JSON object, for example {example}. Use it for samplers that have no box above. A setting that has its own box above is refused. If a server refuses a setting, it is left out and the reply still comes."] = "Дополнительные настройки, которые добавляются к каждому ответу, в виде объекта JSON, например {example}. Используйте их для сэмплеров, для которых нет поля выше. Настройка, для которой есть своё поле выше, отклоняется. Если сервер отклоняет настройку, она пропускается, а ответ всё равно приходит.",
    ["Mistral takes only the settings shown here. Top K, Min P and the advanced JSON are for Local AI and Custom models."] = "Mistral принимает только настройки, показанные здесь. Top K, Min P и расширенный JSON предназначены для моделей Local AI и своих моделей.",
    ["Mistral does not take this setting."] = "Mistral не принимает эту настройку.",
    ["That is not valid JSON."] = "Это некорректный JSON.",
    ["This must be a JSON object, for example {example}."] = "Это должен быть объект JSON, например {example}.",
    ["Too many keys. Keep {max} or fewer."] = "Слишком много ключей. Оставьте не более {max}.",
    ["“{name}” is not a usable key name. Use letters, digits and underscores."] = "“{name}” нельзя использовать как имя ключа. Используйте буквы, цифры и символы подчёркивания.",
    ["“{name}” has its own setting in this form. Use that instead."] = "“{name}” имеет собственную настройку в этой форме. Используйте её.",
    ["Use the Longest reply box for the length of a reply, not “{name}”."] = "Для длины ответа используйте поле «Самый длинный ответ», а не “{name}”.",
    ["“{name}” is set by the mod and cannot be changed here."] = "“{name}” задаётся модом и здесь не может быть изменён.",
    ["“{name}” needs a number, a text, true or false, or a list of those."] = "“{name}” требует число, текст, true или false либо список таких значений.",
    ["Longest character description, in characters"] = "Самое длинное описание персонажа, в символах",
    ["Earlier turns kept"] = "Сохранено обменов",
    ["Right-now sentence"] = "Фраза о текущем моменте",
    ["Notes for this turn"] = "Заметки для этой реплики",
    ["That prompting option was not found."] = "Этот вариант промпта не найден.",
    ["Keep at least one rule."] = "Оставьте хотя бы одно правило.",
    ["Rule {n} is empty. Write the rule or delete it."] = "Правило {n} пустое. Напишите правило или удалите его.",
    ["Rule {n} is too long. Keep each one under {max} characters."] = "Правило {n} слишком длинное. Держите каждое короче {max} символов.",
    ["The rules are too long together. Keep them under {max} characters in all."] = "Правила вместе слишком длинные. Держите их в сумме короче {max} символов.",
    ["This text is too long. Keep it under {max} characters."] = "Текст слишком длинный. Держите его короче {max} символов.",
    ["This text cannot be empty."] = "Текст не может быть пустым.",
    ["Use a number from {min} to {max}."] = "Введите число от {min} до {max}.",
    ["Too many stop texts. Keep {max} or fewer."] = "Слишком много стоп-текстов. Оставьте не более {max}.",
    ["A stop text is too long. Keep each one under {max} characters."] = "Один стоп-текст слишком длинный. Держите каждый короче {max} символов.",
    ["{field}: {message}"] = "{field}: {message}",
    ["In use now"] = "Сейчас в работе",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "Как отвечает каждый вариант беседы. У каждого варианта свой промпт. Изменение учитывается со следующей реплики, перезапуск не нужен.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "Факты, которые персонажи получают из игры, и короткий список фильтров безопасности здесь редактировать нельзя. Промпт Convai хранится на стороне Convai.",
    ["Mistral and Local AI"] = "Mistral и Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite и Standard — два размера модели Local AI. Вариант «для взрослых» используется, пока включён контент для взрослых.",
    ["Your Custom models and APIs"] = "Ваши собственные модели и API",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "Собственная модель появится здесь, когда вы выберете «Свой» в качестве поставщика бесед и укажете модель.",
    ["From {min} to {max}."] = "От {min} до {max}.",
    ["Shipped: {value}"] = "Как в игре: {value}",
    ["Rule {n}"] = "Правило {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "Правило {n}, для говорящего со своей длиной ответа",
    ["Rule {n}, for Mature content"] = "Правило {n}, для контента для взрослых",
    ["Move rule {n} up"] = "Правило {n} вверх",
    ["Move up"] = "Вверх",
    ["Move rule {n} down"] = "Правило {n} вниз",
    ["Move down"] = "Вниз",
    ["Delete rule {n}"] = "Удалить правило {n}",
    ["Other versions of this rule"] = "Другие версии этого правила",
    ["Leave a version empty to use the rule text."] = "Оставьте версию пустой, чтобы использовать текст правила.",
    ["For a speaker with a reply length of its own"] = "Для говорящего со своей длиной ответа",
    ["For Mature content"] = "Для контента для взрослых",
    ["Shipped: off"] = "Как в игре: выкл.",
    ["Shipped: the mod’s own limit"] = "Как в игре: собственный лимит мода",
    ["before V’s words"] = "перед словами V",
    ["after V’s words"] = "после слов V",
    ["Repeat the “where you are” sentence right before V’s words"] = "Повторить фразу «где вы» прямо перед словами V",
    ["The notes for this turn go"] = "Заметки для этой реплики пойдут",
    ["Output rules"] = "Правила вывода",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "Пронумерованные правила, которые модель читает перед каждым ответом. Используйте {name} для имени персонажа и {words} для длины ответа говорящего, у которого она есть.",
    ["Example replies"] = "Примеры ответов",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "Ответы, которые модель видит после правил. Маленькая модель может скопировать их слово в слово, поэтому либо не добавляйте ни одного, либо делайте их короткими и простыми.",
    ["Add an example reply"] = "Добавить пример ответа",
    ["An example reply"] = "Пример ответа",
    ["Example reply {n}"] = "Пример ответа {n}",
    ["Opening line"] = "Первая строка",
    ["The first line of the character text. Use {name} for the character’s name."] = "Первая строка текста персонажа. Используйте {name} для имени персонажа.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "Последнее, что модель читает перед ответом. Используйте {name} для имени персонажа и {words} для длины ответа. Настройка контента для взрослых добавляет после этого свою фразу.",
    ["Section headings"] = "Заголовки разделов",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "Заголовки, которые отмечают каждую часть промпта. Меняйте формулировки, но не порядок.",
    ["Layout"] = "Разметка",
    ["Where some notes go in the prompt."] = "Где в промпте стоят некоторые заметки.",
    ["Sampling"] = "Выборка",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "Насколько свободно модель подбирает слова ответа. Оставьте поле пустым, чтобы использовать значение из игры.",
    ["Length limits"] = "Ограничения длины",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "Сократите то, что читает модель, — ответы будут быстрее. Ограничения мода всё равно действуют, поэтому эти настройки могут только сокращать.",
    ["Stop texts"] = "Стоп-тексты",
    ["Mature layer"] = "Слой для взрослых",
    ["The wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "Формулировки, которые добавляются, когда включён Контент для взрослых. Мод выбирает откровенную или намекающую версию строки в зависимости от того, что разрешает загруженная модель, поэтому редактируйте ту версию, которую использует ваша модель. Пустое поле убирает эту строку. Строка только для взрослых и жёсткие ограничения всегда добавляются в конце и не редактируются.",
    ["Speech line"] = "Строка речи",
    ["Word bank"] = "Словарь слов",
    ["Romance line"] = "Строка о романтике",
    ["Closing clause"] = "Заключительная фраза",
    ["Tone line"] = "Строка тона",
    ["Partner paragraph: affection and desire"] = "Абзац о партнёре: привязанность и желание",
    ["Partner paragraph: nothing invented"] = "Абзац о партнёре: ничего не выдумывать",
    ["{part}, for models that allow explicit sex"] = "{part}, для моделей, которые допускают откровенный секс",
    ["{part}, for models that keep sex suggestive"] = "{part}, для моделей, которые оставляют секс намёком",
    ["This option does not get the Mature layer."] = "Этот вариант не получает слой для взрослых.",
    ["Mature layer and closing line, for models that allow explicit sex"] = "Слой для взрослых и последняя строка, для моделей, которые допускают откровенный секс",
    ["Mature layer and closing line, for models that keep sex suggestive"] = "Слой для взрослых и последняя строка, для моделей, которые оставляют секс намёком",
    ["A reply ends when the model writes one of these. Line breaks count. Up to {max}."] = "Ответ заканчивается, когда модель пишет один из них. Переносы строк считаются. До {max}.",
    ["Add a stop text"] = "Добавить стоп-текст",
    ["A text that ends the reply"] = "Текст, который завершает ответ",
    ["Stop text {n}"] = "Стоп-текст {n}",
    ["Preview"] = "Просмотр",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "Текст промпта так, как его читала бы модель для примерного персонажа. Он следует за вашими правками по мере ввода, ещё до сохранения.",
    ["Sample character name"] = "Имя примерного персонажа",
    ["A speaker with a reply length of its own"] = "Говорящий со своей длиной ответа",
    ["Reply length in words"] = "Длина ответа в словах",
    ["Mature content is on"] = "Контент для взрослых вкл.",
    ["The preview waits until the problems in the form are fixed."] = "Предпросмотр ждёт, пока будут исправлены ошибки в форме.",
    ["No example replies."] = "Нет примеров ответов.",
    ["No closing line."] = "Нет последней строки.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "Вернуть исходный промпт для {name}? Ваши изменения в этой части будут удалены.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "Вернуть исходный промпт для {name}? Все ваши изменения в нём будут удалены.",
    ["Back to the shipped prompting."] = "Вернуть исходный промпт.",
    ["Prompting"] = "Промпт",
    ["Street reputation"] = "Уличная репутация",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "Банды, NCPD, корпорации и жители каждого района помнят, что сделал V: Street Cred, решения в заказах, драки, преступления на глазах полиции и то, как ты обращаешься с людьми. От этого зависят приветствие, доверие и помощь.\n\nТолько обычные люди, не именные и не сюжетные персонажи. Меняет их слова, ничего в игре.",
    ["NPCs react to threats and commands"] = "NPC реагируют на угрозы и приказы",
    ["Ordinary people you threaten run, cower or fight back, as their kind would: gang members and guards use their fists for an insult and their weapons for a death threat.\n\nThey may also do what you tell them, if they would: get down, stop, or get out of the vehicle.\n\nOnly ordinary people, never named or story characters, and never during scenes, quests or fights."] = "Обычные люди, которым ты угрожаешь, убегают, сжимаются от страха или дают отпор, как свойственно их типу: члены банд и охранники отвечают на оскорбление кулаками, а на угрозу смерти оружием.\n\nОни также могут сделать то, что ты им скажешь, если сделали бы: лечь на землю, остановиться или выйти из машины.\n\nТолько обычные люди, никогда персонажи с именем или из сюжета, и никогда во время сцен, заданий или боёв.",
    ["Voice language"] = "Язык голоса",
    ["English"] = "английский",
    ["Automatic"] = "Авто",
    ["Polish"] = "польский",
    ["Russian"] = "русский",
    ["Ukrainian"] = "украинский",
    ["Turkish"] = "турецкий",
    ["Czech"] = "чешский",
    ["Hungarian"] = "венгерский",
    ["Japanese"] = "японский",
    ["Korean"] = "корейский",
    ["Chinese"] = "китайский",
    ["Choose one of the listed reply languages."] = "Выберите один из перечисленных языков ответа.",
    ["No speech was heard. Hold the talk key while you speak."] = "Речь не услышана. Удерживайте клавишу голоса, пока говорите.",
    ["Voice activation"] = "Голосовая активация",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "Голосовой активации не удалось открыть микрофон. Проверьте устройство ввода в Windows.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "Голосовой ввод не смог подключиться к Convai. Удерживайте клавишу голоса ещё раз или введите текст.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Говорите без удержания клавиши. Когда вы смотрите на персонажа или рядом спутник, мод слушает и отвечает, если вы делаете паузу около секунды.\n\nНикогда во время собственных сцен и выбора реплик или пока говорит персонаж. С вашего ПК ничего не уходит, пока не услышана речь. Лучше наушники; микрофон Bluetooth-гарнитуры переводит их в режим разговора на время прослушивания.",
    ["Opening microphone…"] = "Открытие микрофона…",
    ["Speak now"] = "Говорите сейчас",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Введите текст в поле поиска, чтобы найти модель по имени или записи, например «rita wheeler». Достаточно части слова.",
    ["Content packs"] = "Наборы контента",
    ["Add-ons that change how the characters talk."] = "Дополнения, которые меняют манеру речи персонажей.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "Наборы контента добавляют правила после ваших. Здесь их нельзя изменить: выключите набор в игре в разделе Настройки > Наборы контента.",
    ["From the content pack {name}"] = "Из набора контента {name}",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Наборы контента, которые меняют этот промпт: {names}. Ваши изменения остаются поверх их, а Сбросить до стандартного возвращает формулировку набора.",
    ["Memory in use"] = "Используемая память",
    ["Normal memory"] = "Обычная память",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Удалить воспоминания очищает только память, показанную здесь. Другая память остаётся без изменений.",
    ["This clears the memory in use: {memory}."] = "Это очистит используемую память: {memory}.",
    ["Backspace"] = "Backspace",
    ["Cancelled."] = "Отменено.",
    ["Caps lock"] = "Caps Lock",
    ["Choose a key or a controller button."] = "Выберите клавишу или кнопку геймпада.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Выберите клавиши и кнопки геймпада для разговора голосом или текстом, групповых чатов и управления напарниками. Они работают сразу.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Выберите клавиши и кнопки геймпада для действий мода. Нажмите «Задать», затем нужную клавишу или кнопку. Esc или B отменяет выбор. Изменение работает сразу, а клавиши, назначенные в Cyber Engine Tweaks, продолжают работать. Выбирайте клавиши, которые игра не использует.",
    ["Controller {button}"] = "Геймпад: {button}",
    ["D-pad down"] = "Крестовина вниз",
    ["D-pad left"] = "Крестовина влево",
    ["D-pad right"] = "Крестовина вправо",
    ["D-pad up"] = "Крестовина вверх",
    ["Down arrow"] = "Стрелка вниз",
    ["End"] = "End",
    ["Enter"] = "Enter",
    ["Group text chat"] = "Групповой текстовый чат",
    ["Group voice chat"] = "Групповой голосовой чат",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Удерживайте, чтобы говорить со всеми персонажами рядом сразу, и отпустите, чтобы отправить. Если ни на кого не смотреть, вы говорите с первым членом вашей группы и ещё с двумя членами группы.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Удерживайте, чтобы говорить с Джонни, голосом в вашей голове, куда бы вы ни смотрели, и отпустите, чтобы отправить. Для этого в Настройках должен быть включён параметр «Джонни в вашей голове».",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Удерживайте клавишу или кнопку, пока говорите, и отпустите, чтобы отправить, как клавишу разговора в Cyber Engine Tweaks. Если ни на кого не смотреть, вы говорите с первым членом вашей группы.",
    ["Home"] = "Home",
    ["Insert"] = "Insert",
    ["Key bindings"] = "Назначение клавиш",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Для назначения клавиш нужен Codeware, а его в этой игре нет. Откройте «Справку», чтобы узнать, что отсутствует.",
    ["Key or button"] = "Клавиша или кнопка",
    ["Left arrow"] = "Стрелка влево",
    ["Menu"] = "Меню",
    ["No key was pressed, so nothing changed."] = "Клавиша не нажата, поэтому ничего не изменилось.",
    ["Not available"] = "Недоступно",
    ["Not set"] = "Не задано",
    ["Num lock"] = "Num Lock",
    ["Page down"] = "Page Down",
    ["Page up"] = "Page Up",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Нажмите сюда, затем нужную клавишу или кнопку геймпада. Esc или B отменяет выбор. Работает сразу.",
    ["Press it to open the Companion Manager while you play."] = "Нажмите, чтобы открыть управление напарниками во время игры.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Нажмите, чтобы написать персонажу, на которого вы смотрите. Если ни на кого не смотреть, вы пишете первому члену вашей группы.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Нажмите, чтобы написать Джонни, голосу в вашей голове, куда бы вы ни смотрели. Для этого в Настройках должен быть включён параметр «Джонни в вашей голове».",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Нажмите, чтобы сразу написать всем персонажам рядом. Если ни на кого не смотреть, вы пишете первому члену вашей группы и ещё двум членам группы.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Нажмите клавишу или кнопку геймпада для действия «{action}». Esc или B отменяет выбор.",
    ["Print screen"] = "Print Screen",
    ["Remove the key or button you set here."] = "Удалите клавишу или кнопку, назначенную здесь.",
    ["Right arrow"] = "Стрелка вправо",
    ["Scroll lock"] = "Scroll Lock",
    ["Space"] = "Пробел",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Разговор текстом",
    ["Talk by voice"] = "Разговор голосом",
    ["Talk to Johnny by text"] = "Разговор с Джонни текстом",
    ["Talk to Johnny by voice"] = "Разговор с Джонни голосом",
    ["That key is already used for another action."] = "Эта клавиша уже назначена на другое действие.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Не удалось загрузить назначение клавиш мода. Откройте «Справку», чтобы узнать, что не так.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Скрипты мода не загрузились, поэтому назначить клавишу нельзя. Откройте «Справку», чтобы узнать, что не так.",
    ["Up arrow"] = "Стрелка вверх",
    ["View"] = "Просмотр",
    ["{action} cleared."] = "Назначение «{action}» очищено.",
    ["{action} is set to {key}."] = "«{action}» назначено на {key}.",
    ["{key} is already used for {other}. Choose another."] = "Клавиша {key} уже используется для «{other}». Выберите другую.",
    ["10 minutes"] = "10 минут",
    ["2 minutes"] = "2 минуты",
    ["5 minutes"] = "5 минут",
    ["Cancel this meeting. She is not told."] = "Отменить встречу. Она не узнает.",
    ["Car"] = "Машина",
    ["Choose how long she waits."] = "Выберите, сколько она ждёт.",
    ["Choose how she arrives."] = "Выберите, как она приедет.",
    ["Choose one of the listed options."] = "Выберите один из вариантов.",
    ["Choose when she arrives."] = "Выберите, когда она приедет.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Напарники приходят к вам, когда вы их приглашаете: пешком или на машине, пишут, ждут и помнят, если вы так и не пришли.\n\nПо умолчанию выключено.",
    ["Fine. Call me when you know what you want."] = "Ладно. Позвони, когда решишь, чего хочешь.",
    ["How long she waits"] = "Сколько она ждёт",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Сколько она ждёт вас после прибытия прямо сейчас. После прибытия по таймеру она ждёт столько, сколько выбрана задержка. Ожидание прекращается во время боя, сцены или меню.",
    ["How she arrives"] = "Как она приезжает",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "Я ждала {minutes} минут в {place}, а ты так и не пришёл. Забудь.",
    ["I'm here at {place}. Where are you?"] = "Я на {place}. Ты где?",
    ["Immersive invitations"] = "Иммерсивные приглашения",
    ["In 10 minutes"] = "Через 10 мин",
    ["In 2 minutes"] = "Через 2 мин",
    ["In 5 minutes"] = "Через 5 мин",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Пригласите напарника, и она правда придёт к вам: появится вне поля зрения, придёт пешком или приедет на машине, напишет, когда будет на месте, и будет ждать вас.",
    ["Meet at my waypoint when I ask"] = "Встречаться у моей метки по просьбе",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Выкл.: «Пригласить» сразу приводит напарника к вам.\n\nВкл.: напарник, которого вы пригласили кнопкой «Пригласить», во вкладке «Контакты» или сообщением, идёт к вам и приходит через время, выбранное здесь. Она пишет, когда на месте, ждёт и уходит сердитой (и помнит это), если вы так и не придёте.",
    ["Right now"] = "Сейчас",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Сейчас: она выходит, как только будет готова.\n\nЧерез 2, 5 или 10 минут: реальные минуты игры, так что она придёт в это время. Потом ждёт столько же, сколько задержка.",
    ["She texts you"] = "Она пишет вам",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Она пишет, когда приходит, когда вы отменяете и когда сдаётся. Выкл.: без сообщений (она всё равно помнит, что её бросили).",
    ["Something came up and I can't make it. Sorry."] = "Что-то случилось, я не смогу. Извини.",
    ["Walk"] = "Пешком",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "Пешком: она появляется вне вашего поля зрения и идёт к вам.\n\nМашина: если рядом дорога, она подъезжает, останавливается на дороге, выходит и идёт остаток пути пешком. Без дороги идёт пешком. Машина остаётся рядом для поездки и исчезает, когда она покидает вашу группу или вы оба уходите от неё далеко.",
    ["When she arrives"] = "Когда она приходит",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Если вы просите её прийти к вашей метке и метка на карте установлена, она идёт туда и сообщает об этом. Выкл.: она всегда приходит туда, где вы.",
    ["Your position cannot be read yet."] = "Пока невозможно определить ваше местоположение.",
    ["on her way"] = "в пути",
    ["the meeting spot"] = "место встречи",
    ["waiting at {place}"] = "ждёт в {place}",
    ["{name} is already on the way."] = "{name} уже в пути.",
    ["{name} is on her way."] = "{name} в пути.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} в пути. Примерно {minutes} мин.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: Рада тебя видеть. Поехали.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Пусть съедет",
    ["That companion is not available."] = "Этот напарник недоступен.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "У тебя нет этой квартиры.",
    ["at home"] = "дома",
    ["out"] = "не дома",
    ["with you"] = "с тобой",
    ["{count} more housemates"] = "ещё {count} соседей по квартире",
    ["{name} has moved out."] = "{name} больше не живёт у тебя.",
    ["{name} is back at home."] = "{name} снова дома.",
    ["{name} joins you."] = "{name} присоединяется к тебе.",
    ["{name} moves into {apartment}."] = "{name} переезжает в {apartment}.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} теперь живёт в {apartment} и остаётся в вашей группе, пока не отправится домой.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} больше не живёт у тебя. Всё остальное остаётся как было.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · живёт в {apartment} · {state}",
    ["Companions change outfits"] = "Напарники меняют наряд",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Напарники из вашей группы время от времени меняют наряд: другой образ днём и ночью, а дома — повседневную одежду, если она есть у персонажа.\n\nТолько когда вы на них не смотрите, никогда на виду, и только для собственных копий вашей группы, никогда для персонажей самой игры. Если выключить эту опцию, они останутся в том, что носят сейчас.",
    ["Choose how often companions speak up."] = "Выберите, как часто спутники подают голос.",
    ["Companions speak up"] = "Спутники подают голос",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Как себя чувствует V по данным других модов, если они установлены: например, усталость, голод, жажда, нервы и зависимости из Dark Future. А также то, что V видимо носит, пока включён наряд из Equipment-EX, чтобы персонажи описывали наряд, а не скрытую под ним одежду.\n\nПо умолчанию выключено. Выкл.: ничего не отправляется, и из этих модов ничего не читается.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Сколько времени прошло с последнего разговора V с этим персонажем, в игре и в реальных днях: с прошлой ночи или несколько дней назад. Говорится только тогда, когда пауза достаточно долгая, и не повторяется в том же разговоре.\n\nВыкл.: ничего не отправляется, и мод перестаёт читать игровые часы для этого.",
    ["Music and TV"] = "Музыка и TV",
    ["Other mods’ state"] = "Состояние других модов",
    ["Speaks up normally"] = "Подаёт голос обычно",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Песня, которая играет на автомобильном радио, когда V едет с персонажем, или на карманном радио V, а также то, что показывают на телевизоре рядом с V.\n\nВыкл.: ничего не отправляется, и мод перестаёт читать это из игры.",
    ["Time since last talk"] = "Время с последнего разговора",
    ["Companions in your party sometimes start talking on their own, at a calm moment or after a scene. With two or more near you, it is often a short chat between up to three of them, and you can join in by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often (the default): about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Спутники иногда сами начинают говорить: в спокойный момент или после сцены. Когда рядом двое или больше, часто завязывается короткий разговор между не более чем тремя, и вы можете вступить в него. Никогда во время боя, сцен, звонков или в меню.\n\nРедко: около 2 за час игры. Обычно: около 4. Часто (по умолчанию): около 6.\n\nКогда Johnny тоже подаёт голос, обе частоты складываются, и говорят они по очереди.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand отвечает на клавиши «Разговор с Джонни» как голос в голове V, когда сюжет его туда помещает. Назначьте клавишу «Разговор с Джонни» на странице «Назначение клавиш»: по умолчанию не назначена.\n\nВкл.: отвечает, когда с ним говорят. Редко: он подаёт голос сам, около 2 раз в час. Обычно: около 4. Часто: около 6.\n\nЕсли спутники тоже подают голос, частоты складываются и говорят по очереди.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Выберите, какую живую информацию об игре передавать персонажам, например место, время, погоду, спутников, здоровье, деньги, снаряжение, задания, музыку и TV и состояние других модов.\n\nПо умолчанию всё включено, кроме состояния других модов, оно выключено. Выключенный вид не отправляется ни одному провайдеру разговоров.",
    ["Housemates"] = "Соседи по квартире",
    ["Housemates talk to each other"] = "Соседи разговаривают друг с другом",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Когда двое или больше соседей дома с вами, они время от времени разговаривают друг с другом.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Персонажи, которым вы говорите, что они могут остаться у вас, переезжают в ваши квартиры и живут там.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Персонажи, которым вы говорите, что они могут остаться у вас, переезжают в ваши квартиры и живут там.\n\nПо умолчанию выключено.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Вкл.: персонажи, которым вы говорите, что они могут остаться у вас, переезжают в ваши квартиры и живут там, и вы можете взять их с собой.\n\nВыкл.: ничего из этого не работает. При выключении они съезжают из ваших квартир, но запоминается, кто там жил, поэтому при включении они возвращаются.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "код OmniVoice не смог загрузиться",
    ["PyTorch is not installed in it"] = "PyTorch не установлен в нём",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Ваш собственный Python (omni-python.txt) проходит тестирование. Откройте эту страницу снова через минуту.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Ваш собственный Python (omni-python.txt) проверяется, когда запускается OmniVoice или когда эта страница проверяет снова.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Ваш собственный Python (omni-python.txt) запускает OmniVoice с {backend} на {card}. Экспериментально.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Ваш собственный Python (omni-python.txt) не использовался: {reason}. OmniVoice использует Python Runtime, которому требуется карта NVIDIA.",
    ["a test on the graphics card failed"] = "тест на видеокарте не пройден",
    ["it did not start or did not answer in time"] = "он не запустился или не ответил вовремя",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "его PyTorch не нашёл видеокарту (без CUDA или ROCm)",
    ["the OmniVoice pack is not installed"] = "пакет OmniVoice не установлен",
    ["the file does not name a python.exe that exists"] = "файл не указывает на существующий python.exe",
    ["the module {module} is missing in it"] = "модуль {module} отсутствует в нём",
    ["1 minute"] = "1 минута",
    ["2 people"] = "2 человека",
    ["3 people"] = "3 человека",
    ["4 people"] = "4 человека",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Все персонажи, которые живут в твоем доме, съезжают одновременно, из всех квартир. Члены группы, которые там не живут, не затрагиваются. Сосед по квартире, который с тобой, остается в твоей группе.",
    ["Evict"] = "Пусть съедет",
    ["Evict all housemates"] = "Пусть съедут все соседи по квартире",
    ["Housemates in one chat"] = "Соседи по квартире в одном чате",
    ["Housemates moved out: {count}"] = "Соседи по квартире съехали: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Как долго соседи по квартире молчат после чата, прежде чем могут начать другой. Параметр Спутники подают голос по-прежнему ограничивает, сколько чатов приходит в час.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "Сколько соседей по квартире присоединяются к одному чату, когда столько людей дома рядом друг с другом. Они говорят по одному. С меньшим количеством дома чат может быть как можно больше.",
    ["Move-in apartment"] = "Квартира для переезда",
    ["Nobody lives at your place."] = "У тебя никто не живет.",
    ["Pause between chats"] = "Пауза между чатами",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Где персонаж переезжает, когда ты говоришь, что может остаться, но не называешь квартиру и не стоишь в одной из своих.\n\nСпроси меня: она спрашивает, какую. Иначе она берет квартиру, которую ты выбираешь здесь. Указаны только квартиры, которыми ты владеешь.",
    ["Ask me"] = "Спроси меня",
    ["Could not start"] = "Не удалось запустить",
    ["Did not start"] = "Не запустилось",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Если папка есть, в самом новом логе в red4ext/logs указано, почему RED4ext её не загрузил: антивирус удалил файл или нет Visual C++ runtime.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Сначала загрузите сохранение. Клавишу можно назначить только при загруженной игре.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "Нажатие клавиши до мода не дошло, поэтому ничего не изменилось. Если клавиши не работают из этого меню, назначьте клавишу в разделе назначения клавиш Cyber Engine Tweaks: это работает так же.",
    ["Runtime incomplete"] = "Runtime неполный",
    ["Runtime not loaded"] = "Runtime не загружен",
    ["Service not running ({reason})"] = "Служба не запущена ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "Плагин Runtime загружен, но служба бесед в этой сессии не оставила следов. В launcher.log в red4ext/plugins/AiNpcCyberpunkCode написано почему: launcher.ini отключён, Node не найден или Node заблокирован программой безопасности. Исправьте это и перезапустите игру.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "Служба бесед не видит папку этого мода в игре: виртуальные папки менеджера модов или папку, которую ей не разрешено читать. Распакуйте Runtime прямо в папку Cyberpunk 2077 или запускайте игру из менеджера модов, в котором лежит Runtime.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "Служба бесед была запущена, но так и не ответила. Вероятно, программа безопасности сразу её остановила, или Node не может работать на этом ПК. Разрешите red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe в своей программе безопасности и перезапустите игру.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows не позволила игре запустить службу бесед (ошибка {error}). Программа безопасности может блокировать node.exe в red4ext/plugins/AiNpcCyberpunkMod/app/node: разрешите его и перезапустите игру.",
    ["Add a server address first."] = "Сначала добавьте адрес сервера.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Три раза спрашивает сервер, кто он, и показывает, доступен ли он, как быстро отвечает и его версию. Речь не отправляется.",
    ["Connected. The server speaks with {voice}."] = "Подключено. Сервер говорит голосом {voice}.",
    ["Custom voices"] = "Пользовательские голоса",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Удаляет сохранённый адрес сервера. Для речи Удалённому OmniVoice он нужен.",
    ["It answers in {ms} ms."] = "Отвечает за {ms} мс.",
    ["Its voice runs on {device}."] = "Его голос работает на {device}.",
    ["Loading"] = "Загрузка",
    ["Not connected. Replies show as text until the server answers."] = "Не подключено. Ответы показываются текстом, пока сервер не ответит.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "По этому адресу никто не ответил. Проверьте, запущен ли сервер, верны ли адрес и порт и находятся ли оба ПК в одной сети. Сервер, запущенный с настройками по умолчанию, слушает только свой ПК: запустите его с адресом прослушивания 0.0.0.0.",
    ["Off. OmniVoice runs on this PC."] = "Выключено. OmniVoice работает на этом ПК.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "Включено, но адрес сервера не сохранён. OmniVoice пока не может говорить.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "Включено, но адрес сервера не сохранён. Пока вы не добавите адрес, используется Pocket.",
    ["On, but no server address is saved. The server is not used yet."] = "Включено, но адрес сервера не сохранён. Сервер пока не используется.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "Включено, но в «Голоса напарников» выбран облачный голос, поэтому сервер не используется.",
    ["On. Waiting for the conversation service."] = "Включено. Ожидание службы разговоров.",
    ["Paste address"] = "Вставить адрес",
    ["Remote OmniVoice"] = "Удалённый OmniVoice",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "Выводить голоса на другом ПК или видеокарте с сервером OmniVoice, чтобы этот ПК сохранял частоту кадров.\n\nВключите, нажмите «Применить» и добавьте адрес сервера ниже. Сервер затем озвучивает каждый выбор Pocket или OmniVoice в «Голоса напарников»; облачный голос остаётся выбранным. Если сервер недоступен, ответы показываются текстом, а мод повторяет попытку каждые несколько секунд.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "Выводить голоса OmniVoice на другом ПК или видеокарте, где работает сервер OmniVoice.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Выводить голоса Pocket и OmniVoice на другом ПК или видеокарте: переключатель вкл./выкл., адрес сервера и проверка подключения. Работает независимо от того, какой из этих голосов выбран выше.",
    ["Server address"] = "Адрес сервера",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Что-то ответило, но это не сервер OmniVoice. Проверьте порт.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "Запустите сервер OmniVoice на другом ПК. Его окно покажет адрес, например 192.168.1.20:8765. Скопируйте его и выберите «Вставить адрес». Он один раз считывается из буфера обмена и сохраняется на этом компьютере.\n\nНа том же ПК используйте 127.0.0.1:8765. Также можно написать address=192.168.1.20:8765 в файле player-remote-omnivoice.txt в папке службы разговоров.\n\nНичего не отправляется, пока Удалённый OmniVoice не включён и не выбран OmniVoice или пока вы не нажмёте «Проверить».",
    ["Status"] = "Состояние",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "Сервер OmniVoice недоступен. Ответы показываются текстом, пока он не ответит. Мод повторяет запрос каждые несколько секунд.",
    ["The clipboard does not hold a server address."] = "В буфере обмена нет адреса сервера.",
    ["The clipboard is empty. Copy the address first."] = "Буфер обмена пуст. Сначала скопируйте адрес.",
    ["The port must be a number from 1 to 65535."] = "Порт должен быть числом от 1 до 65535.",
    ["The server address was removed."] = "Адрес сервера удалён.",
    ["The server answered but could not load its voice. Its window says why."] = "Сервер ответил, но не смог загрузить свой голос. Его окно сообщает причину.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "Сервер ответил, но ещё загружает свой голос. Попробуйте через минуту.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "Сервер другой версии. Используйте папку сервера и мод из одного выпуска.",
    ["The server is ready."] = "Сервер готов.",
    ["The server refused the request."] = "Сервер отклонил запрос.",
    ["The server took too long to answer."] = "Сервер слишком долго не отвечал.",
    ["Use the address only: no user name, no path, no #."] = "Укажите только адрес: без имени пользователя, пути и #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Укажите адрес, который показывает окно сервера, например 192.168.1.20:8765, без https://.",
    ["Waiting for the server to answer…"] = "Ожидание ответа сервера…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Используется ли сейчас сервер. Проверяется, когда нужен голос, а после сбоя каждые несколько секунд, но никогда во время игры.",
    ["Your own character, made in the character editor."] = "Ваш собственный персонаж, созданный в редакторе персонажей.",
    ["Build for your game"] = "Сборка для вашей игры",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Ваша игра — {game}, но Runtime — для игры {runtime}. Скачайте полный установочный zip для игры {game} со страницы мода на Nexus Mods (основной файл для игры 2.5, необязательный файл для игры 2.31), распакуйте в папку Cyberpunk 2077 поверх текущих файлов и перезапустите игру.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Get the update zip for game {game} from the mod’s Nexus Mods page (the update file is for game 2.5, the optional update file for game 2.31) and install it over these, then restart the game."] = "Ваша игра — {game}, но Scripts — сборка для игры {scripts}. Скачайте zip-обновление для игры {game} со страницы мода на Nexus Mods (файл обновления для игры 2.5, необязательный файл обновления для игры 2.31), установите поверх текущих и перезапустите игру.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over these, then restart the game."] = "Ваша игра — {game}, но Scripts и Runtime — сборка для игры {scripts}. Скачайте полный установочный zip для игры {game} со страницы мода на Nexus Mods (основной файл для игры 2.5, необязательный файл для игры 2.31) и распакуйте в папку Cyberpunk 2077 поверх текущих файлов, затем перезапустите игру.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts — сборка для игры {scripts}, а Runtime — сборка для игры {runtime}, и версия игры не совпадает ни с одной из них. Распакуйте полный установочный zip для той же игры, что и у вас (со страницы на Nexus Mods), в папку Cyberpunk 2077, затем перезапустите игру.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Runtime — для игры {other}, у вас игра {game}. Получите полный ZIP для {game}.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "Scripts — для игры {other}, у вас игра {game}. Получите ZIP обновления для {game}.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Мод для игры {other}, у вас игра {game}. Получите полный ZIP для {game}.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts — для игры {scripts}, Runtime — для {runtime}. Должны совпадать. См. Справку.",
    ["Choose one of the listed microphones."] = "Выберите один из перечисленных микрофонов.",
    ["Microphone"] = "Микрофон",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "Микрофон, выбранный в настройках ({chosen}), не подключён, поэтому используется вход Windows по умолчанию: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "Микрофон, выбранный в настройках, не подключён, поэтому используется вход Windows по умолчанию.",
    ["Windows default"] = "Windows по умолчанию",
    ["not connected"] = "не подключён",
    ["{name}, chosen in Settings > Voices."] = "{name}, выбран в Настройки > Голоса.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, вход Windows по умолчанию. Другой выбирается в Настройки > Голоса > Микрофон.",
    ["Revenge ambushes"] = "Засады из мести",
    ["Speak dialogue choices"] = "Произнесение вариантов реплик",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "Назовите вариант реплики, чтобы выбрать его: его слова, часть слов или его номер (\"два\", \"последний\"). Если ничего не подходит явно, ничего не выбирается. Ни один персонаж не отвечает.\n\nНажимает стрелки и Enter, поэтому игра должна быть в фокусе. Нужно распознавание речи на этом ПК. Лучше всего работают наушники.",
    ["No option matched. Say its number."] = "Подходящего варианта нет. Назовите его номер.",
    ["Two options fit. Say its number."] = "Подходят два варианта. Назовите номер нужного.",
    ["Speaking a choice needs speech recognition on this PC."] = "Для произнесения варианта нужно распознавание речи на этом ПК.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "ROCm PyTorch от AMD пока не поддерживает эту карту.",
    ["Another setup is already running. Wait for it to finish."] = "Другая установка уже запущена. Подожди, пока она завершится.",
    ["Cancelled"] = "Отменено",
    ["Cancelling…"] = "Отменяется…",
    ["Checking your card…"] = "Проверка твоей карты…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "Загрузка: {done} из {total} MB ({percent}%)",
    ["Downloading…"] = "Загрузка…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "Экспериментально. Pocket говорит, пока OmniVoice не готов. Локальный голос никогда не переключается на облачный.",
    ["Frees about {disk} GB."] = "Освобождает около {disk} GB.",
    ["Frees the space it took."] = "Освобождает место, которое занимала.",
    ["Install"] = "Установить",
    ["Installed"] = "Установлено",
    ["Installed. OmniVoice uses it when it starts."] = "Установлено. OmniVoice использует её при запуске.",
    ["It is kept in the mod’s data folder on drive C:."] = "Хранится в папке данных мода на диске C:.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "Работает в фоне, пока ты играешь. Игра продолжает работать, и ничего другого не меняется.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "Занимает около {disk} GB на диске C: в папке данных мода.",
    ["MIOpen convolutions (AMD)"] = "Свёртки MIOpen (AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "Недоступно на этом ПК. Нужны видеокарта AMD Radeon и пакет OmniVoice.",
    ["OmniVoice for AMD"] = "OmniVoice для AMD",
    ["OmniVoice on AMD: set up first"] = "OmniVoice на AMD: сначала настрой",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "Тогда OmniVoice на этой карте больше не запускается, пока её снова не настроят.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "Вкл.: MIOpen от AMD выполняет свёртки, с MIOPEN_FIND_MODE=2 и MIOPEN_FIND_ENFORCE=1. Выкл.: собственные свёртки PyTorch. Что быстрее, зависит от карты и драйвера: если голоса медленные или обрываются на середине, попробуй другой вариант. Только для карт AMD. OmniVoice перезапустится с новым выбором, когда будет простаивать.",
    ["Own Python"] = "Свой Python",
    ["Ready"] = "Готово",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "Готово. OmniVoice работает на {card} с ROCm от AMD.",
    ["Reinstall"] = "Переустановить",
    ["Remove AMD setup"] = "Удалить установку AMD",
    ["Removing the AMD setup…"] = "Удаление установки AMD…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "Запусти OmniVoice на своей видеокарте AMD Radeon с ROCm от AMD: одна загрузка, настрой её отсюда.",
    ["Set up OmniVoice for AMD"] = "Настроить OmniVoice для AMD",
    ["Starting the AMD setup…"] = "Запуск установки AMD…",
    ["Testing it on your card…"] = "Проверка на твоей карте…",
    ["The AMD setup was removed."] = "Установка AMD удалена.",
    ["The OmniVoice pack is not installed. Install it first."] = "Пакет OmniVoice не установлен. Сначала установи его.",
    ["The conversation service is not running. Restart the game."] = "Служба разговоров не запущена. Перезапусти игру.",
    ["The download did not finish. Check your connection and try again."] = "Загрузка не завершилась. Проверь подключение и попробуй снова.",
    ["The download is not ready yet in this version of the mod."] = "Загрузка в этой версии мода пока недоступна.",
    ["The downloaded files did not check out. Try again."] = "Скачанные файлы не прошли проверку. Попробуй снова.",
    ["The files could not be unpacked. Try again."] = "Файлы не удалось распаковать. Попробуй снова.",
    ["The setup did not finish. Try again."] = "Установка не завершилась. Попробуй снова.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "Установка не прошла проверку на твоей карте, поэтому OmniVoice не может её использовать.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "Установка есть, но не прошла проверку на твоей карте. Выбери «Переустановить».",
    ["There is not enough free space on drive C:. Free some up and try again."] = "На диске C: мало свободного места. Освободи немного и попробуй снова.",
    ["This PC has no AMD Radeon card this setup can use."] = "На этом ПК нет видеокарты AMD Radeon, которую может использовать эта установка.",
    ["Unpacking…"] = "Распаковка…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "Вместо этого используется твой Python (omni-python.txt). Удали этот файл, чтобы использовать эту установку.",
    ["your AMD card"] = "твоя карта AMD",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: сначала настрой",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "Настройка для AMD (Настройки > Голоса > OmniVoice для AMD) запускает OmniVoice с ROCm на {card}. Экспериментально.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "Настройка для AMD не использовалась: {reason}. Выбери «Переустановить» в Настройки > Голоса > OmniVoice для AMD. До тех пор говорит Pocket.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "Берите эдди в долг у персонажей, одалживайте им и возвращайте долги в разговоре. У каждого свои деньги, он решает, исходя из того, как относится к вам. Время от времени они просят о займе.\n\nЭдди переходят из рук в руки, как только персонаж соглашается, и только с вашими персонажами (команда, гости, соседи). Персонажи игры только говорят об этом. Выключено по умолчанию.",
    ["Eddies with characters"] = "Эдди с персонажами",
    ["The eddies could not be moved."] = "Эдди не удалось перевести.",
    ["You do not have enough eddies for that."] = "На это у вас недостаточно эдди.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} больше нет с вами, поэтому эдди не переводились.",
    ["Add to favorites"] = "Добавить в избранное",
    ["One download of about {size} GB."] = "Одна загрузка, около {size} GB.",
    ["One download."] = "Одна загрузка.",
    ["Use the Search box, top right"] = "Используйте поле поиска",
    ["Search by name"] = "Поиск по имени",
    ["Search"] = "Найти",
    ["The search box could not open."] = "Не удалось открыть поле поиска.",
    ["Type part of a name"] = "Введите часть имени",
    ["Opens a text box over the game. Type part of a name and press Enter: the list shows every match on every page and letter. Esc leaves the list as it is, and Enter on an empty box shows the whole list again. Case and accents do not matter, and every word you type has to match the start of a word in the name."] = "Открывает текстовое поле поверх игры. Введите часть имени и нажмите Enter: список покажет все совпадения на всех страницах и буквах. Esc оставляет список как есть, а Enter в пустом поле снова показывает весь список. Регистр и диакритика не важны, а каждое введённое слово должно совпадать с началом слова в имени.",
    ["How to search"] = "Как искать",
    ["search: {query} · {count} found"] = "поиск: {query} · найдено {count}",
    ["Empties the Search box and shows the whole list again."] = "Очищает поле поиска и снова показывает весь список.",
    ["Click the Search box at the top right of this panel (it is dim until you click it) and type a name. The list shows every match on every page and letter. Case and accents do not matter, and every word you type has to match the start of a word in the name."] = "Нажмите на поле поиска в правом верхнем углу этой панели (пока вы на него не нажали, оно тусклое) и введите имя. Список покажет все совпадения на всех страницах и буквах. Регистр и диакритика не важны, а каждое введённое слово должно совпадать с началом слова в имени.",
    ["Click the Search box at the top right of this panel and type a name."] = "Нажмите на поле поиска в правом верхнем углу этой панели и введите имя.",
    ["Remove {name} from favorites"] = "Убрать {name} из избранного",
    ["Remove {name}"] = "Убрать {name}",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "Одной загрузкой настройте OmniVoice на видеокарте AMD Radeon и выберите, как он будет работать.",
    ["That entry cannot be a favorite."] = "Этот пункт нельзя добавить в избранное.",
    ["You have too many favorites. Remove one first."] = "Избранного слишком много. Сначала удалите одно.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "Ваша видеокарта AMD Radeon ({card}) может запускать OmniVoice. Настройте его в Настройки > Голоса > OmniVoice для AMD: одна загрузка, потом он запустится сам.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "Не удалось сохранить избранное, поэтому оно сохранится только до закрытия игры.",
    ["{count} matching characters"] = "Подходящих персонажей: {count}",
    ["{name} is no longer a favorite."] = "{name} больше не в избранном.",
    ["A saved party holds {count} characters, so the rest were left out."] = "В сохранённую группу помещается {count} персонажей, поэтому остальные не попали в неё.",
    ["Already with you: {names}."] = "Уже с вами: {names}.",
    ["Another saved party already has that name."] = "Другая сохранённая группа уже имеет такое имя.",
    ["Could not invite: {names}."] = "Не удалось пригласить: {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "Удаляет эту сохранённую группу. Персонажи в вашей текущей группе не затрагиваются.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "Приглашает персонажей этой группы к вам: {names}.\n\nОни добавляются в вашу группу, и никто не отпускается. Персонаж, который уже с вами, не приглашается дважды. Тех, кто не может прийти, называют вместе с причиной.",
    ["Parties"] = "Группы",
    ["Party"] = "Группа",
    ["Press Delete again to delete {name}."] = "Нажмите «Удалить» ещё раз, чтобы удалить {name}.",
    ["Press again"] = "Нажмите ещё раз",
    ["Press again to delete this saved party. Anything else cancels."] = "Нажмите ещё раз, чтобы удалить эту сохранённую группу. Любое другое действие отменяет удаление.",
    ["Rename"] = "Переименовать",
    ["Rename party"] = "Переименовать группу",
    ["Renamed to {name}."] = "Переименовано в {name}.",
    ["Replaces the characters of this saved party with the ones in your party now."] = "Заменяет персонажей этой сохранённой группы на тех, кто сейчас в вашей группе.",
    ["Save current party"] = "Сохранить текущую группу",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "Сохранено как {name}. Нажмите под ним «Пригласить группу», чтобы пригласить их снова.",
    ["Saved party: {name}"] = "Сохранённая группа: {name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "Сохраняет персонажей, которые сейчас в вашей группе, включая копии и ваших собственных персонажей, как группу, которую можно пригласить снова одним нажатием. Она называется Группа 1, Группа 2 и так далее и появляется ниже.\n\nМожно сохранить до {count} групп.",
    ["Spawn"] = "Пригласить",
    ["Spawn party"] = "Пригласить группу",
    ["That party no longer exists."] = "Такой группы больше нет.",
    ["The characters of this party: {names}."] = "Персонажи этой группы: {names}.",
    ["The party could not be saved."] = "Не удалось сохранить группу.",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "В этом меню нет текстового поля, поэтому группа сохраняет имя. В Mod Configuration Menu оно есть: введите имя в его поле поиска.",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "Введите новое имя в поле поиска вверху (Mod Configuration Menu), затем нажмите «Переименовать». В Native Settings UI нет текстового поля, поэтому там группа сохраняет имя.",
    ["Type the new name in the Search box first, then press Rename."] = "Сначала введите новое имя в поле поиска, затем нажмите «Переименовать».",
    ["Update"] = "Обновить",
    ["Update with current party"] = "Обновить текущей группой",
    ["You can keep {count} saved parties. Delete one first."] = "Можно сохранить {count} групп. Сначала удалите одну.",
    ["Your party is empty. Invite someone first."] = "Ваша группа пуста. Сначала пригласите кого-нибудь.",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "Сохранённые группы не удалось записать на диск, поэтому они сохранятся только до закрытия игры.",
    ["that character model is unavailable"] = "модель персонажа недоступна",
    ["the invitation was refused"] = "приглашение отклонено",
