    ["{name} has nobody to invite."] = "{name}: некого приглашать.",
    ["{name} now has the characters of your party."] = "У {name} теперь персонажи вашей группы.",
    ["{party}: inviting {names}."] = "{party}: приглашаются {names}.",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "Добавляет {name} в избранное. Избранное выводится в начале страницы 1 и первым во вкладке «Чат» телефона. Обновления его не затрагивают.",
    ["Favorites"] = "Избранное",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "Здесь показаны только первые {count} из избранного. Остальные — в списке ниже.",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "Страница {page} из {pages}: {kind} с {first} по {last}.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "Нажмите, чтобы перейти на страницу {page} из {pages}: {kind} с {first} по {last}.",
