    ["This is the first page."] = "Это первая страница.",
    ["This is the last page."] = "Это последняя страница.",
    ["characters"] = "персонажи",
    ["entries"] = "записи",
    ["models"] = "модели",
    ["{count} more favorites"] = "Ещё {count} в избранном",
    ["{name} is now a favorite. Favorites are at the top of page 1."] = "{name} добавлен в избранное. Избранное выводится в начале страницы 1.",
    ["Favorite"] = "Избранное",
